"""Package completed real-browser recordings as MP4s and a local review gallery."""
import json, subprocess, os
from pathlib import Path
root=Path(os.environ.get('RECORDING_OUTPUT', str(Path(__file__).resolve().parents[3]/'output'/'rails-demo'))).resolve()
items=json.loads((root/'manifest.json').read_text())
unique={x['slug']:x for x in items}
items=sorted(unique.values(),key=lambda x:x['slug'])
for item in items:
    stem=root/item['slug']; mp4=stem.with_suffix('.mp4')
    if not mp4.exists() or (stem.with_suffix('.webm').exists() and stem.with_suffix('.webm').stat().st_mtime > mp4.stat().st_mtime):
        subprocess.run(['ffmpeg','-y','-loglevel','error','-i',str(stem.with_suffix('.webm')),'-c:v','libx264','-threads','2','-preset','veryfast','-crf','23','-pix_fmt','yuv420p','-movflags','+faststart',str(mp4)],check=True)
    duration=float(subprocess.check_output(['ffprobe','-v','error','-show_entries','format=duration','-of','default=nw=1:nk=1',str(mp4)]))
    item['duration']=round(duration)
    item['mediaVersion']=str(mp4.stat().st_mtime_ns)
    if not stem.with_suffix('.jpg').exists() or mp4.stat().st_mtime > stem.with_suffix('.jpg').stat().st_mtime:
        subprocess.run(['ffmpeg','-y','-loglevel','error','-ss',str(min(duration/3,20)),'-i',str(mp4),'-frames:v','1','-q:v','3',str(stem.with_suffix('.jpg'))],check=True)
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FreeDME · Actual Rails walkthroughs</title><style>
*{box-sizing:border-box}body{margin:0;background:#f2f6fb;color:#173650;font:16px/1.5 system-ui,sans-serif}header{background:#143858;color:white;padding:28px max(24px,calc((100vw - 1400px)/2))}h1{font-size:32px;line-height:1.2;margin:8px 0}header p{max-width:850px;color:#dce7f3;margin:8px 0}.eyebrow{font-size:12px;letter-spacing:.12em;color:#a8cfff;font-weight:700}main{max-width:1448px;margin:auto;padding:24px;display:grid;grid-template-columns:300px minmax(0,1fr);gap:24px}nav{display:flex;flex-direction:column;gap:8px}button,select,textarea{font:inherit}button{cursor:pointer;border:1px solid #c7d6e7;border-radius:9px;background:white;text-align:left;padding:13px;color:#173650}button:hover,button[aria-current=true]{background:#e0edff;border-color:#6493c8}button small{display:block;color:#60768c;font-size:12px;margin-top:4px}h2{font-size:22px;margin:0 0 12px}video{width:100%;display:block;background:#102537;max-height:70vh;border-radius:12px}section{min-width:0}.controls{display:flex;align-items:center;flex-wrap:wrap;gap:18px;margin:16px 0}a{color:#215aa1}.notice{padding:14px 18px;border:1px solid #c9dcee;background:#e8f1fb;border-radius:10px;font-size:14px}.feedback{background:white;border:1px solid #dce5f0;padding:18px;border-radius:12px;margin-top:18px}textarea{display:block;width:100%;min-height:90px;margin:10px 0;padding:12px;border:1px solid #c4d2e4;border-radius:7px}button:focus-visible,a:focus-visible,textarea:focus-visible{outline:3px solid #3477c7;outline-offset:3px}.small{font-size:13px;color:#5d7288}select{padding:7px;border-radius:6px}footer{max-width:1400px;margin:0 auto;padding:0 24px 24px;font-size:13px;color:#5d7288}@media(max-width:800px){main{display:block;padding:16px}nav{flex-direction:row;overflow:auto;margin-bottom:20px}nav button{min-width:230px}header{padding:24px 16px}h1{font-size:26px}}
</style></head><body><header><div class="eyebrow">FREEDME / REVIEW LIBRARY</div><h1>The actual website, step by step.</h1><p>Recorded journeys through the Rails application. Watch the real forms, dashboards, transaction changes and simulated SMS from each participant’s perspective.</p></header><main><nav id="menu" aria-label="Recorded journeys"></nav><section><h2 id="title"></h2><video id="player" controls playsinline preload="metadata"></video><div class="controls"><label>Playback speed <select id="speed"><option value="0.25">0.25×</option><option value="0.5">0.5×</option><option value="0.75">0.75×</option><option value="1" selected>1×</option><option value="1.25">1.25×</option><option value="1.5">1.5×</option></select></label><a id="download" download>Download MP4</a><a id="transcript" download hidden>Download transcript</a><button id="restart">Replay from start</button></div><div class="notice"><strong>Real Rails actions · Fictional sandbox</strong><br>Recorded on a separate database. OTP, SMS and AWS extraction/screening responses are simulated. No personal documents or live messages were used. A highlighted cursor follows the actions, and orange ripples mark clicks. Every role switch shows the mobile-number and simulated OTP sign-in screens after a role-change notice. Captions identify any test-clock changes. Videos include computer-generated narration and on-screen explanations. Use the player volume control to mute the voice, or enable English narration captions.</div><div class="feedback"><label for="notes"><strong>Reviewer feedback</strong></label><p class="small">Notes for this video are saved in this browser. Export them to share with the project team.</p><textarea id="notes" placeholder="What worked? What should change? Include the video timestamp if useful."></textarea><button id="export">Export feedback</button><span id="saved" class="small" role="status"></span></div></section></main><footer><a href="REVIEW-NOTES.txt">Workflow review notes</a> · <a href="verification.txt">Outcome checks</a><br>These demonstrations do not establish production readiness. The loan video demonstrates a confirmed return; overdue reminder policy remains unresolved. <a href="http://127.0.0.1:3002/">Explore the sandbox on this computer</a> · <a href="http://127.0.0.1:3002/test-data">Test users</a> · <a href="reviewer-demo.html">Interactive overview</a></footer><script>
const items=__ITEMS__, $=id=>document.getElementById(id);let selected=0,notes={};try{notes=JSON.parse(localStorage.getItem('freedme-recording-notes')||'{}')}catch(_){}function save(){notes[items[selected].slug]=$('notes').value;try{localStorage.setItem('freedme-recording-notes',JSON.stringify(notes));$('saved').textContent=' Saved locally.'}catch(_){$('saved').textContent=' Export to keep these notes.'}}function show(i){selected=i;const x=items[i];$('title').textContent=x.title;$('player').src=x.slug+'.mp4?v='+x.mediaVersion;$('player').poster=x.slug+'.jpg?v='+x.mediaVersion;$('player').playbackRate=+$('speed').value;$('player').preservesPitch=true;$('player').querySelectorAll('track').forEach(t=>t.remove());if(x.narrated){const t=document.createElement('track');t.kind='captions';t.label='English narration';t.srclang='en';t.src=x.slug+'.vtt?v='+x.mediaVersion;$('player').append(t)}$('transcript').hidden=!x.narrated;$('transcript').href=x.slug+'-transcript.txt';$('download').href=x.slug+'.mp4';$('notes').value=notes[x.slug]||'';$('saved').textContent='';document.querySelectorAll('[data-i]').forEach(b=>b.setAttribute('aria-current',+b.dataset.i===i));history.replaceState(null,'','#'+x.slug)}items.forEach((x,i)=>{const b=document.createElement('button');b.dataset.i=i;b.textContent=x.title;const small=document.createElement('small');small.textContent=Math.floor(x.duration/60)+':'+String(x.duration%60).padStart(2,'0')+' · actual Rails recording';b.append(small);b.onclick=()=>{save();show(i)};$('menu').append(b)});$('notes').oninput=save;$('speed').onchange=()=>$('player').playbackRate=+$('speed').value;$('restart').onclick=()=>{$('player').currentTime=0;$('player').play()};$('export').onclick=()=>{save();const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),feedback:items.map(x=>({video:x.title,note:notes[x.slug]||''})).filter(x=>x.note)},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='FreeDME-recording-feedback.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};show(Math.max(0,items.findIndex(x=>'#'+x.slug===location.hash)));
</script></body></html>'''
(root/'index.html').write_text(html.replace('__ITEMS__',json.dumps(items)))
(root/'manifest.json').write_text(json.dumps(items,indent=2))
print(f'Packaged {len(items)} recordings')

(root/'reviewer-demo.html').write_text((Path(__file__).resolve().parents[2]/'public'/'reviewer-demo.html').read_text())

# Role notices work offline and pause playback independently of playback speed.
cues_path = root/'role-cues.json'
if not cues_path.exists(): cues_path = Path(__file__).with_name('role-cues.json')
if cues_path.exists():
    cues = json.loads(cues_path.read_text())
    for item in items:
        if item.get('roleNoticesEmbedded'): cues.pop(item['slug'], None)
    script = 'window.FreeDMERoleCues = ' + json.dumps(cues) + ';\n' + Path(__file__).with_name('role-playback.js').read_text()
    (root/'role-playback.js').write_text(script)
    gallery=root/'index.html'
    gallery.write_text(gallery.read_text().replace('</body>', '<script src="role-playback.js"></script></body>'))
